        .tick_rate(100_hz)
        .name("my-robot");

    auto cmd_pub = sched.advertise<horus::msg::CmdVel>("cmd_vel");

    sched.add("controller")
        .rate(50_hz)
        .budget(5_ms)
        .on_miss(horus::Miss::Skip)
        .tick([&] {
            auto sample = cmd_pub.loan();
