using namespace horus::literals;

// Simulated temperature sensor
static float read_temperature() {
    static int tick = 0;
    return 22.0f + 5.0f * std::sin(tick++ * 0.1f);  // oscillates 17-27°C
}

int main() {
    // Create scheduler at 10 Hz
    horus::Scheduler sched;
    sched.tick_rate(10_hz);
    sched.name("temp_monitor");

    // Create pub/sub — both share the same SHM topic
    horus::Publisher<horus::msg::CmdVel> sensor_pub("temp.reading");
    horus::Subscriber<horus::msg::CmdVel> monitor_sub("temp.reading");

    // Sensor node: reads temperature, publishes it
    sched.add("sensor")
        .order(0)           // runs first
        .tick([&] {
            auto sample = sensor_pub.loan();     // zero-copy from SHM
            sample->linear = read_temperature();  // store temp in linear field
            sample->timestamp_ns = 0;
            sensor_pub.publish(std::move(sample));
        })
        .build();

    // Monitor node: reads temperature, checks threshold
    sched.add("monitor")
        .order(10)          // runs after sensor
        .tick([&] {
            auto msg = monitor_sub.recv();
            if (!msg) return;

            float temp = msg->get()->linear;
            if (temp > 25.0f) {
                std::printf("[ALERT] Temperature %.1f°C exceeds threshold!\n", temp);
            } else {
                std::printf("[OK]    Temperature %.1f°C\n", temp);
            }
        })
        .build();

    std::printf("Starting temperature monitor (Ctrl+C to stop)...\n");
    sched.spin();  // blocks until stopped
}

use horus::prelude::*;
use std::time::Duration;

// ── Sensor Node ─────────────────────────────────────────────
// Publishes a simulated temperature reading every second.

struct TemperatureSensor {
    publisher: Topic<f32>,
    temperature: f32,
}

impl TemperatureSensor {
    fn new() -> Result<Self> {
        Ok(Self {
            publisher: Topic::new("temperature")?,
            temperature: 20.0,
        })
    }
}

impl Node for TemperatureSensor {
    fn name(&self) -> &str {
        "TemperatureSensor"
    }

    fn tick(&mut self) {
        self.temperature += 0.1;
        self.publisher.send(self.temperature);

        // WARNING: sleep() in tick() blocks the scheduler thread.
        // In production, use .rate(1_u64.hz()) on the node builder instead.
        std::thread::sleep(Duration::from_secs(1));
    }

    fn shutdown(&mut self) -> Result<()> {
        eprintln!("Sensor shutting down. Last reading: {:.1}°C", self.temperature);
        Ok(())
    }
}

// ── Monitor Node ────────────────────────────────────────────
// Subscribes to temperature readings and prints them.

struct TemperatureMonitor {
    subscriber: Topic<f32>,
}

impl TemperatureMonitor {
    fn new() -> Result<Self> {
        Ok(Self {
            subscriber: Topic::new("temperature")?,
        })
    }
}

impl Node for TemperatureMonitor {
    fn name(&self) -> &str {
        "TemperatureMonitor"
    }

    fn tick(&mut self) {
        if let Some(temp) = self.subscriber.recv() {
            println!("Temperature: {:.1}°C", temp);
        }
    }

    fn shutdown(&mut self) -> Result<()> {
        eprintln!("Monitor shutting down.");
        Ok(())
    }
}

// ── Main ────────────────────────────────────────────────────

fn main() -> Result<()> {
    eprintln!("Starting temperature monitoring system...\n");

    let mut scheduler = Scheduler::new();

    // The scheduler auto-detects order from topics:
    // sensor publishes "temperature", monitor subscribes → sensor runs first
    scheduler.add(TemperatureSensor::new()?).build()?;
    scheduler.add(TemperatureMonitor::new()?).build()?;

    // Run until Ctrl+C
    scheduler.run()?;

    Ok(())
}

