        self.odom.twist.linear[0] = dx * 100.0;  // dx per tick * rate
        self.odom.twist.angular[2] = dtheta * 100.0;
        self.odom.set_frames("odom", "base_link");
        self.odom_pub.send(self.odom);
    }
